struct Uniforms {
    size: f32
};

@group(0) @binding(0) var output_tex: texture_storage_3d<r32float, write>;
@group(0) @binding(1) var<uniform> uniforms: Uniforms;

fn sdSphere(o: vec3<f32>, radius: f32) -> f32 {
    return length(o) - radius;
}

fn map(p: vec3<f32>) -> f32 {
    return sdSphere(p, uniforms.size);
}


@compute @workgroup_size(8, 8, 4)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let dims = textureDimensions(output_tex);
    if (global_id.x >= dims.x || global_id.y >= dims.y || global_id.z >= dims.z) {
        return;
    }

    let uvw = vec3<f32>(global_id) / vec3<f32>(dims);
    var o = uvw * 2.0 - 1.0;

    let distance = map(o);
    let color = vec4<f32>(distance, 1.0, 1.0, 1.0);

    textureStore(output_tex, vec3<i32>(global_id.xyz), color);
}

// Standard full-screen quad vertex shader
struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
};

@vertex
fn vs_main(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {
    var out: VertexOutput;
    let x = f32(i32(vertex_index & 1u)) * 2.0 - 1.0;
    let y = f32(i32(vertex_index >> 1u)) * 2.0 - 1.0;
    out.position = vec4<f32>(x, y, 0.0, 1.0);
    out.uv = vec2<f32>(x * 0.5 + 0.5, 0.5 - y * 0.5);
    return out;
}

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
};

struct Uniforms {
    time: f32,
    resolution: vec2<f32>
};

const COLORS: array<vec3<f32>, 4> = array<vec3<f32>, 4>(
    vec3<f32>(1.0, 0.0, 0.0), // red
    vec3<f32>(0.0, 1.0, 0.0), // green
    vec3<f32>(0.0, 0.0, 1.0), // blue
    vec3<f32>(1.0, 1.0, 1.0)  // white
);

@group(0) @binding(0) var my_sampler: sampler;
@group(0) @binding(1) var<uniform> uniforms: Uniforms;
@group(0) @binding(2) var distance_: texture_3d<f32>;
@group(0) @binding(3) var bone_index: texture_3d<u32>;

fn map(p: vec3<f32>) -> f32 {
    return textureSampleLevel(distance_, my_sampler, p * 0.25, 0.0).x;
}

fn calcNormal(p: vec3<f32>) -> vec3<f32> {
    let texel = 1.0 / vec3<f32>(textureDimensions(distance_));
    let e = texel.x;

    let ex = vec3<f32>(e, 0.0, 0.0);
    let ey = vec3<f32>(0.0, e, 0.0);
    let ez = vec3<f32>(0.0, 0.0, e);

    let n = vec3<f32>(
        map(p + ex) - map(p - ex),
        map(p + ey) - map(p - ey),
        map(p + ez) - map(p - ez),
    );

    return normalize(n);
}

struct Raymarch {
    hit: bool,
    point: vec3<f32>,
    normal: vec3<f32>,
    distance: f32,
};

fn raymarch(origin: vec3<f32>, direction: vec3<f32>) -> Raymarch {
    const MAX_STEPS = 40;
    const SURF_DIST = 0.01;

    var t = 0.0;
    for (var i = 0; i < MAX_STEPS; i = i + 1) {
        var p = origin + direction * t;
        let d = map(p);
        let n = calcNormal(p);
        let cosTheta = abs(dot(direction, n));
        var step = d * (1.0 + 1.0 * (1.0 - cosTheta));
        if (d < SURF_DIST) {
            /*
            var a = t - step;
            var b = t;
			for(var i = 0; i < 0; i++) {
				t = (a + b) * 0.5;
				let d = map(origin + direction * t);
				if(d <= 0.) {
				    b = t;
                } else {
                    a = t;
                }
			}
			let p = origin + direction * t;
			*/
            return Raymarch(true, p, n, t);
        }
        t += step;
    }

    return Raymarch(false, vec3(0.0), vec3(0.0), t);
}

fn raytrace(origin: vec3<f32>, direction: vec3<f32>, bounces: i32) -> vec3<f32> {
    let light_dir = normalize(vec3(1.0, -1.0, -1.0));
    const sphere_color = vec3(1.0, 0.9, 0.8);

    var color = vec3(0.0);
    var ro = origin;
    var rd = direction;
    var t = 0.0;
    for (var i = 0; i < 3; i++) {
        var r0 = raymarch(ro, rd);    
        if (r0.hit) {
            t += r0.distance;
            // Direct lighting at first hit
            let luminance = max(dot(light_dir, r0.normal), 0.0) * 0.5;
            color += sphere_color * luminance / t * 2.0;

            // Reflection ray
            rd = normalize(reflect(rd, r0.normal));
            ro = r0.point + rd * 0.1;
        } else {
            break;
        }
    }
    return color;
}

@fragment
fn fs_main(in: VertexOutput) -> @location(0) vec4<f32> {
    let p = (in.uv.xy * 2.0 - 1.0) * (uniforms.resolution.x / uniforms.resolution.y);
    let rd = normalize(vec3(p, 1.0)) * vec3(1.0, 1.0, 1.0);
    let ro = vec3<f32>(2.0, 2.0, 1.0);

    var color = vec3(0.0, 0.0, 0.0);
    let result = raymarch(ro, rd);
    if result.hit {
        let index: vec4<u32> = textureLoad(bone_index, vec3<u32>(result.point * vec3<f32>(textureDimensions(bone_index).xyz) * 0.25), 0);
        color = COLORS[index.x];
        color = color * (0.25 + 0.75 * dot(result.normal, normalize(vec3(1.0, -1.0, -1.0))));
    }

    return vec4<f32>(color, 1.0);
}

struct Map {
    distance: f32,
    bone: u32
}

fn MapMin(a: Map, b: Map) -> Map {
    if a.distance < b.distance {
        return a;
    } else {
        return b;
    }
}

// Shapes

fn sdBox(p: vec3<f32>, b: vec3<f32>) -> f32 {
  let q = abs(p) - b;
  return length(max(q, vec3(0.0))) + min(max(q.x, max(q.y, q.z)), 0.0);
}

fn sdCappedCone(p: vec3<f32>, a: vec3<f32>, b: vec3<f32>, ra: f32, rb: f32) -> f32 {
    let rba  = rb-ra;
    let baba = dot(b-a,b-a);
    let papa = dot(p-a,p-a);
    let paba = dot(p-a,b-a)/baba;
    let x = sqrt( papa - paba*paba*baba );
    var cax = max(0.0, x - select(rb, ra, paba < 0.5));
    let cay = abs(paba-0.5)-0.5;
    let k = rba*rba + baba;
    let f = clamp( (rba*(x-ra)+paba*baba)/k, 0.0, 1.0 );
    let cbx = x-ra - f*rba;
    let cby = paba - f;
    let s = select(1.0, -1.0, cbx < 0.0 && cay < 0.0);
    return s * sqrt( min(cax*cax + cay*cay*baba,
                     cbx*cbx + cby*cby*baba) );
}

fn sdCapsule(
    p: vec3<f32>,
    a: vec3<f32>,
    b: vec3<f32>,
    r0: f32,
    r1: f32
) -> f32 {
    let d = b - a;
    let h = length(d);
    let dn = d / h;
    let t = clamp(dot(p - a, dn), 0.0, h);
    return distance(a + t * dn, p) - mix(r0, r1, t / h);
}

fn sdCapsuleF(
    p: vec3<f32>,
    a: vec3<f32>,
    b: vec3<f32>,
    r0: f32,
    r1: f32,
    f: f32
) -> f32 {
    let d = b - a;
    let h = length(d);
    let dn = d / h;
    let t = dot(p - a, dn);
    let th = t / h;
    let rr = mix(r0, r1, th)
           * max(0.0, 1.0 + f - f * 4.0 * abs(th - 0.5) * abs(th - 0.5));
    return distance(a + clamp(t, 0.0, h) * dn, p) - rr;
}

fn sdSphere(p: vec3<f32>, s: f32) -> f32 {
    return length(p) - s;
}

fn sdCylinder(p: vec3<f32>, h: vec2<f32>) -> f32 {
    let d = abs(vec2<f32>(length(p.xz), p.y)) - h;
    return min(max(d.x, d.y), 0.0) + length(max(d, vec2<f32>(0.0)));
}

fn sdRoundBox(p: vec3<f32>, b: vec3<f32>, r: f32) -> f32
{
  let q = abs(p) - b + r;
  return length(max(q, vec3(0.0))) + min(max(q.x,max(q.y,q.z)), 0.0) - r;
}

fn sdRoundCone(p: vec3<f32>, a: vec3<f32>, b: vec3<f32>, r1: f32, r2: f32) -> f32
{
    let ba = b - a;
    let l2 = dot(ba,ba);
    let rr = r1 - r2;
    let a2 = l2 - rr*rr;
    let il2 = 1.0/l2;

    let pa = p - a;
    let y = dot(pa,ba);
    let z = y - l2;
    let x2 = dot( pa*l2 - ba*y, pa*l2 - ba*y );
    let y2 = y*y*l2;
    let z2 = z*z*l2;

    // single square root!
    let k = sign(rr)*rr*rr*x2;
    if( sign(z)*a2*z2>k ) {
        return  sqrt(x2 + z2) * il2 - r2;
    }
    if( sign(y)*a2*y2<k ) {
        return  sqrt(x2 + y2) * il2 - r1;
    }
    return (sqrt(x2*a2*il2)+y*rr)*il2 - r1;
}

fn sdABRoundBox(pos: vec3<f32>, a: vec3<f32>, b: vec3<f32>, a_size: vec2<f32>, b_size: vec2<f32>, a_radius: f32, b_radius: f32, x: f32) -> f32 {
    let center = (a + b) * 0.5;
    let diff = b - a;
    let extension = abs(diff) * 0.5;
    let x_offset = center.x;
    let y_offset = mix(a.y, b.y, x);
    let z_offset = mix(a.z, b.z, x);
    let offset = vec3(x_offset, y_offset, z_offset);
    let size_x = extension.x;
    let size_y = mix(a_size.x, b_size.x, x);
    let size_z = mix(a_size.y, b_size.y, x);
    let size = vec3(size_x, size_y, size_z);
    let radius = mix(a_radius, b_radius, x);
    return sdRoundBox(pos - offset, size, radius);
}


// Helpers

fn pointInLine(pos: vec3<f32>, a: vec3<f32>, b: vec3<f32>) -> f32 {
    let ab = b - a;
    let ap = pos - a;
    let t = dot(ap, ab) / dot(ab, ab);
    return t;
}

fn smin(a: f32, b: f32, k: f32) -> f32 {
    let h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

fn opRep(p: vec3<f32>, c: vec3<f32>) -> vec3<f32> {
    return (p % c) - 0.5 * c;
}

fn rotationZ(angle: f32) -> mat3x3<f32> {
    let c = cos(angle);
    let s = sin(angle);

    return mat3x3<f32>(
        vec3( c, -s, 0.0),
        vec3( s,  c, 0.0),
        vec3(0.0, 0.0, 1.0)
    );
}

// Map

const UNKNOWN_INDEX: u32 = 0;
const ARM_INDEX: u32 = 3;
const LEG_INDEX: u32 = 2;
const TORSO_INDEX: u32 = 1;

fn foot(p: vec3<f32>, size: vec3<f32>) -> Map {
    // separate it in three parts: hindfoot, midfoot and forefoot
    let pos = vec3(-p.z, p.y, p.x);
    let len = size.x / 2.0;
    let height = size.y / 2.0;
    let width = size.z / 2.0;
    let start_size = vec2(height, width);
    let end_size = vec2(height * 0.5, width);
    let a = vec3(0., start_size.x, 0.0);
    let b = vec3(len, end_size.x, 0.0);
    let pil = pointInLine(pos, a, b);
    let distance = sdABRoundBox(pos, a, b, start_size, end_size, start_size.x, end_size.x, pil);
    return Map(distance, LEG_INDEX);
}

fn leg(pos: vec3<f32>, size: vec2<f32>) -> Map {
    let start_radius = size.x;
    let end_radius = size.x;
    let distance = sdRoundCone(pos - vec3(0.0, start_radius, 0.0), vec3(0.0, 0.0, 0.0), vec3(0.0, size.y, 0.0), start_radius, end_radius);
    return Map(distance, LEG_INDEX);
}

fn lower_limb(pos: vec3<f32>, leg_size: vec2<f32>, foot_size: vec3<f32>) -> Map {
    var m = foot(pos, foot_size);
    return MapMin(m, leg(pos, leg_size));
}

fn lower_limbs(pos: vec3<f32>, leg_size: vec2<f32>, foot_size: vec3<f32>, body_width: f32) -> Map {
    let distance = body_width / 2.0 - leg_size.x;
    return lower_limb(vec3(abs(pos.x) - distance, pos.yz), leg_size, foot_size);
}

fn torso(pos: vec3<f32>, size: vec3<f32>) -> Map {
    let distance = sdRoundBox(pos, size / 2.0, size.z * 0.25);
    return Map(distance, TORSO_INDEX);
}

fn arm(pos: vec3<f32>, size: vec2<f32>) -> Map {
    let start_radius = size.x;
    let end_radius = size.x;
    let distance = sdRoundCone(pos - vec3(0.0, start_radius, 0.0), vec3(0.0, 0.0, 0.0), vec3(0.0, size.y, 0.0), start_radius, end_radius);
    return Map(distance, ARM_INDEX);
}

fn hand(p: vec3<f32>, size: vec3<f32>) -> Map {
    let distance = sdRoundBox(p, size, size.z * 0.5);
    return Map(distance, ARM_INDEX);
}

const PI: f32 = acos(-1.0);

fn upper_limb(p: vec3<f32>, arm_size: vec2<f32>, hand_size: vec3<f32>) -> Map {
    let shoulder = vec3(0.0, arm_size.y, 0.0);

    let rot = rotationZ(-PI / 8.0);
    let pos = transpose(rot) * (p - shoulder) + shoulder;

    var m = hand(pos, hand_size);
    m = MapMin(m, arm(pos, arm_size));
    return m;
}

fn upper_limbs(pos: vec3<f32>, arm_size: vec2<f32>, hand_size: vec3<f32>, body_width: f32) -> Map {
    let limbs_distance = body_width / 2.0 + arm_size.x;
    let m = upper_limb(vec3(abs(pos.x) - limbs_distance, pos.yz), arm_size, hand_size);
    return m;
}

fn neck(pos: vec3<f32>, size: vec2<f32>) -> Map {
    let distance = sdRoundCone(pos, vec3(0.0), vec3(0.0, size.y, 0.0), size.x, size.x);
    return Map(distance, UNKNOWN_INDEX);
}

fn head(pos: vec3<f32>, size: vec2<f32>) -> Map {
    let distance = sdRoundCone(pos, vec3(0.0), vec3(0.0, size.y, 0.0), size.x, size.x);
    return Map(distance, UNKNOWN_INDEX);
}

fn character(pos: vec3<f32>, height: f32) -> Map {
    let relative = height * 0.1;
    let leg_radius = 0.25 * relative;
    let leg_length = 3.0 * relative;
    let leg = vec2(leg_radius, leg_length);

    let foot_length = 1.5 * relative;
    let foot_height = 0.5 * relative;
    let foot_width = 0.5 * relative;
    let foot = vec3(foot_length, foot_height, foot_width);

    let torso_width = 1.5 * relative;
    let torso_height = 3.0 * relative;
    let torso_depth = leg_radius * 2.0;
    let torso_size = vec3(torso_width, torso_height, torso_depth);

    let arm_radius = 0.25 * relative;
    let arm_length = 2.5 * relative;
    let arm = vec2(arm_radius, arm_length);

    let hand_length = 0.3 * relative;
    let hand_height = 0.3 * relative;
    let hand_width = 0.3 * relative;
    let hand = vec3(hand_length, hand_height, hand_width);

    let neck_radius = 0.25 * relative;
    let neck_length = 0.25 * relative;
    let neck_size = vec2(neck_radius, neck_length);

    let head_radius = 0.5 * relative;
    let head_length = 0.3 * relative;
    let head_size = vec2(head_radius, head_length);

    var m = lower_limbs(pos, leg, foot, torso_width);
    m = MapMin(m, torso(pos - vec3(0.0, leg_length + leg_radius + torso_height * 0.5, 0.0), torso_size));
    m = MapMin(m, upper_limbs(pos - vec3(0.0, leg_length + torso_height - arm.y - arm.x, 0.0), arm, hand, torso_width));
    m = MapMin(m, neck(pos - vec3(0.0, leg_length + torso_height + neck_size.x, 0.0), neck_size));
    m = MapMin(m, head(pos - vec3(0.0, leg_length + torso_height + neck_size.x + neck_size.y + head_size.x, 0.0), head_size));
    return m;
}

fn map(p: vec3<f32>) -> Map {
    return character(p, 1.0);
}

struct Uniforms {
    size: f32
};

@group(0) @binding(0) var<uniform> uniforms: Uniforms;
@group(0) @binding(1) var distance_: texture_storage_3d<r32float, write>;
@group(0) @binding(2) var bone_index: texture_storage_3d<rgba8uint, write>;
@group(0) @binding(3) var bone_weight: texture_storage_3d<rgba32float, write>;

@compute @workgroup_size(8, 8, 4)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let dims = textureDimensions(distance_);
    if (global_id.x >= dims.x || global_id.y >= dims.y || global_id.z >= dims.z) {
        return;
    }

    let uvw = vec3<f32>(global_id) / vec3<f32>(dims);
    var o = (uvw * 2.0 - 1.0) * vec3(1.0, 1.0, 1.0) - vec3(0.0, -0.4, 0.0);

    let m = map(o);
    let distance = vec4<f32>(m.distance, 1.0, 1.0, 1.0);
    let bone = vec4<u32>(m.bone);

    let point = vec3<i32>(i32(global_id.x), i32(dims.y) - i32(global_id.y), i32(global_id.z));
    textureStore(distance_, point, distance);
    textureStore(bone_index, point, bone);
    textureStore(bone_weight, point, vec4(1.0));
}
